window.NPC_CHUNK_54 = [{"name":"Mase Darimar","cr":11,"xp":12800,"race":"Half-Elf","gender":"Male","age_category":"Adult","classes":[{"class":"druid of Gozreh","level":8},{"class":"fighter","level":4}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["elf","human"],"init":2,"senses":["low-light vision"],"ac":25,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+8 armor, +1 deflection, +2 Dex, +1 dodge, +3 natural","hp":106,"hd":"8d8+4d10+44","hd_value":12,"fort":14,"ref":5,"will":11,"save_mods":"+1 vs. fear, +2 vs. enchantments, +4 vs. fey and plant-targeted effects","defensive_abilities":["bravery +1","resist nature's lure"],"speed":[{"type":"land","speed":30}],"melee":"+1 Human bane scimitar +16 (1d6+7/15-20) or +1 trident +15 (1d8+7)","ranged":"+1 trident +13 (1d8+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"lightning lord","details":"8 bolts/day"},{"type":"storm burst","details":"1d6+4 nonlethal damage, 7/day"},{"type":"wild shape","details":"3/day"}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":8,"spellsprepared_concentration":12,"spellsprepared":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"air walk"},{"spell":"ball lightning"},{"spell":"freedom of movement"},{"spell":"sleet storm","type":"domain"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"call lightning","type":"domain"},{"spell":"cure moderate wounds"},{"spell":"protection from energy"},{"spell":"quench"},{"spell":"water breathing"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"barkskin"},{"spell":"bull's strength"},{"spell":"fog cloud","type":"domain"},{"spell":"gust of wind"},{"spell":"warp wood"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"cure light wounds"},{"spell":"endure elements"},{"spell":"entangle"},{"spell":"obscuring mist","type":"domain"},{"spell":"speak with animals"},{"spell":"touch of the sea"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"flare"},{"spell":"purify food and drink"},{"spell":"stabilize"}]}],"spelldomains":"Weather","strength":18,"dexterity":15,"constitution":14,"intelligence":10,"wisdom":18,"charisma":8,"baseatk":10,"cmb":14,"cmd":28,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (scimitar)"},{"feat":"Natural Spell"},{"feat":"Sea Legs"},{"feat":"Toughness"},{"feat":"Weapon Focus (scimitar)"},{"feat":"Weapon Specialization (scimitar)"}],"skills":[{"skill":"Acrobatics","value":2},{"skill":"Climb","value":10},{"skill":"Fly","value":6},{"skill":"Handle Animal","value":6},{"skill":"Heal","value":10},{"skill":"Knowledge (geography)","value":7},{"skill":"Knowledge (nature)","value":9},{"skill":"Linguistics","value":1},{"skill":"Perception","value":13},{"skill":"Profession (sailor)","value":12},{"skill":"Spellcraft","value":6},{"skill":"Survival","value":10},{"skill":"Swim","value":16}],"languages":["Common","Aquan","Druidic","Elven","Polyglot"],"sq":["armor training 1","elf blood","nature bond (Weather domain)","nature sense","trackless step","water child","wild empathy +7","woodland stride"],"special_abilities":[{"type":"Water Child","kind":"Ex","details":"Because of his aquatic elf ancestry, Mase gains a +4 racial bonus on Swim checks and can always take 10 while swimming. This alternate racial trait replaces the adaptability and multitalented racial traits."}],"gear":"+2 brine dragonhide breastplate, +1 Human bane scimitar, +1 trident, belt of mighty constitution +2, ring of protection +1, silver holy symbol of Gozreh, spell component pouch, elemental gem (water)","before_combat":"Mase casts barkskin, bull's strength, and protection from energy (fire) on himself ahead of any battle. If he anticipates fighting in the water or close quarters combat, he casts freedom of movement as well.","during_combat":"Initially, Mase prefers to use air walk or wild shape into a Medium air elemental to rise above the battlefield. From that vantage point, he pelts anyone under him with ball lightning, call lightning, sleet storm, or his lightning lord domain ability, utilizing his Natural Spell feat if necessary. He casts warp wood to render the ranged weapons of attackers useless. After softening up his opposition with these tactics, Mase returns to the ground, targeting humans whenever possible with his scimitar.","morale":"If reduced to 25 hit points or fewer, Mase attempts to withdraw, screening himself with fog cloud or obscuring mist so he can wild shape into an elemental and move away at maximum speed.","source":"AP 58"},{"name":"Isawyn","cr":10,"xp":9600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":10,"archetype":"Chelish diva"}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":22,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+7 armor, +2 Dex, +1 dodge, +2 shield","hp":108,"hd":"10d8+60","hd_value":10,"fort":7,"ref":9,"will":9,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","speed":[{"type":"land","speed":30}],"melee":"+1 keen rapier +10 (1d6+2/15-20)","ranged":"mwk composite shortbow +10 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 26 rounds/day","details":"move action, countersong, devastating aria, distraction, fascinate, inspire courage +2, inspire greatness, scathing tirade, suggestion"}],"spellsknown_caster":"bard","spellsknown_caster_level":10,"spellsknown_concentration":14,"spellsknown":[{"spell_level":4,"spell_slots":2,"spells":[{"spell":"dimension door"},{"spell":"dominate person"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"confusion"},{"spell":"crushing despair"},{"spell":"dispel magic"},{"spell":"haste"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds"},{"spell":"detect thoughts"},{"spell":"invisibility"},{"spell":"sound burst"},{"spell":"whispering wind"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"animate rope"},{"spell":"cure light wounds"},{"spell":"disguise self"},{"spell":"unseen servant"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":12,"dexterity":14,"constitution":18,"intelligence":8,"wisdom":10,"charisma":18,"baseatk":7,"cmb":8,"cmd":21,"feats":[{"feat":"Arcane Strike"},{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perform sing)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Bluff","value":23},{"skill":"Diplomacy","value":17},{"skill":"Fly","value":17},{"skill":"Intimidate","value":17},{"skill":"Knowledge (local)","value":7},{"skill":"Knowledge (nobility)","value":7},{"skill":"Linguistics","value":6},{"skill":"Perform (dance)","value":17},{"skill":"Perform (oratory)","value":17},{"skill":"Perform (sing)","value":23},{"skill":"Sense Motive","value":23},{"skill":"Sleight of Hand","value":11}],"languages":["Common","Gnome","Goblin","Infernal","Polyglot"],"sq":["costume proficiency","famous","jack-of-all-trades (use any skill)","prima donna","versatile performance (sing, dance, oratory)"],"special_abilities":[{"type":"Bardic Performance-Devastating Aria","kind":"Su","details":"By spending 1 round of bardic performance as a standard action, Isawyn can direct a burst of sound at a target within 30 feet. This deals 1d4+10 points of sonic damage to an object, or half this amount to a living creature."},{"type":"Bardic Performance-Scathing Tirade","kind":"Su","details":"To affect a creature with a scathing tirade, Isawyn must be within 30 ft. of the target, who must be able to see and hear her. The targeted creature becomes frightened (Will DC 19 reduces the effect to the shaken condition) for as long as Isawyn continues the performance plus 1d4 rounds. This is a mind-affecting fear effect."},{"type":"Costume Proficiency","kind":"Ex","details":"Isawyn is proficient with medium armor and can cast bard spells while wearing medium armor without incurring arcane spell failure chance."},{"type":"Famous","kind":"Ex","details":"Isawyn gains a +3 bonus on Bluff and Intimidate checks made in and around certain parts of central Cheliax-this ability is of little use to her at this time."},{"type":"Prima Donna","kind":"Ex","details":"Isawyn can expend an extra round of bardic performance to gain a +2 bonus on Perform checks or save DCs to her countersong, fascinate, and scathing tirade bardic performances."}],"gear":"+1 glamered breastplate, +1 buckler, +1 keen rapier, masterwork composite shortbow with 20 arrows, spell component pouch, 92 pp, potions of bear's endurance (2)","before_combat":"Isawyn casts unseen servant at the start of every day. She drinks a potion of bear's endurance just before combat.","during_combat":"Isawyn activates her bardic performance to inspire courage, then casts invisibility and uses haste and healing magic to aid Gorebeard and any summoned monsters. She uses her unseen servant to open and close doors, pick up fallen weapons, and otherwise do small tasks during combat to keep opponents on their toes and force them to waste time with move actions to counter these minor inconveniences. She targets the most heavily armored foe with dominate person and orders that person to strip out of his armor, drop his weapons, and then stand patiently in the corner of the room. If the battle turns bad, she risks ordering the dominated person to attack her enemies with his bare hands. If a foe looks like he's only a few points away from being knocked unconscious, Isawyn uses devastating aria to try to knock him out with the damage it causes.","morale":"Isawyn doesn't want to die here; she casts dimension door to escape into the surrounding slums if reduced to fewer than 15 hit points. Isawyn holds grudges, however, and having heard of the PCs' infamous grudge against Harrigan, she seeks him out and joins him in defending his island if she can escape.","source":"AP 59, Pathfinder Campaign Setting Inner Sea Magic 32"},{"name":"Lady Nightshade","cr":10,"xp":9600,"race":"daemon-spawn Tiefling","gender":"Female","age_category":"Adult","classes":[{"class":"illusionist","level":11}],"alignment":"NE","size":"Medium","type":"outsider","sub_types":["native"],"init":3,"senses":["darkvision 60 ft."],"ac":24,"ac_touch":16,"ac_flat_footed":20,"ac_mods":"+4 armor, +2 deflection, +3 Dex, +1 dodge, +4 shield","hp":107,"hd":"11d6+66","hd_value":11,"fort":11,"ref":8,"will":11,"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +6 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"invisibility field","details":"11 rounds/day"}]},{"frequency":"1/day","spells":[{"spell":"death knell"}]},{"frequency":"7/day","spells":[{"spell":"blinding ray"}]}],"spellsprepared_caster":"illusionist","spellsprepared_caster_level":11,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":6,"spell_slots":2,"spells":[{"spell":"quickened mirror image"},{"spell":"summon monster VI"}]},{"spell_level":5,"spell_slots":3,"spells":[{"spell":"persistent image"},{"spell":"quickened shield"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"phantasmal killer"},{"spell":"summon monster IV","count":2}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic"},{"spell":"fly"},{"spell":"lightning bolt"},{"spell":"major image","count":2},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"acid arrow"},{"spell":"bear's endurance"},{"spell":"blur"},{"spell":"glitterdust"},{"spell":"invisibility"},{"spell":"minor image"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"disguise self"},{"spell":"floating disc"},{"spell":"mage armor"},{"spell":"magic missile","count":2},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"open/ close"},{"spell":"prestidigitation"}]}],"prohibited_schools":"enchantment, necromancy","strength":10,"dexterity":16,"constitution":18,"intelligence":18,"wisdom":10,"charisma":8,"baseatk":5,"cmb":5,"cmd":21,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Silent Spell"},{"feat":"Toughness"}],"skills":[{"skill":"Disable Device","value":5},{"skill":"Disguise","value":10},{"skill":"Fly","value":17},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (history)","value":8},{"skill":"Knowledge (local)","value":8},{"skill":"Knowledge (planes)","value":8},{"skill":"Perform (act)","value":7},{"skill":"Sleight of Hand","value":16},{"skill":"Spellcraft","value":18}],"languages":["Common","Abyssal","Aquan","Gnome","Goblin","Infernal","Polyglot"],"sq":["arcane bond (amulet)","contingency (displacement on self if she snaps her fingers as a free action)","extended illusions +5 rounds"],"gear":"masterwork dagger, cloak of resistance +2, ring of protection +2, ring of the ram (17 charges), spellbook, spell component pouch, ivory statuette of herself worth 1,500 gp, 328 gp, wand of grease (48 charges)","before_combat":"Lady Nightshade casts bear's endurance and mage armor.","during_combat":"Lady Nightshade hangs back from combat, casting quickened shield and greater invisibility on the first round and then using summon monster spells each round thereafter. If her invisibility is countered, she casts quickened mirror image on the next round, snapping her fingers at the same time to also activate her contingency spell of displacement.","morale":"Lady Nightshade abandons the troupe if reduced to fewer than 15 hit points, using dimension door to escape into Hell Harbor. After that, she does her best to avoid the PCs and escape the Shackles.","source":"AP 59, Blood of Fiends 19"},{"name":"Gorebeard Trench","cr":10,"xp":9600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":11,"archetype":"savage barbarian"}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":25,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+3 armor, +1 deflection, +2 Dex, +3 dodge, +4 natural, -2 rage, +4 shield","hp":143,"hd":"11d12+66","hd_value":11,"fort":11,"ref":5,"will":9,"save_mods":"+2 vs. fear","defensive_abilities":["improved uncanny dodge","naked courage +2","natural toughness +2"],"speed":[{"type":"land","speed":40}],"melee":"unarmed strike +20 (1d3+9)","ranged":"improvised weapon +13 (1d4+9)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"greater rage","details":"25 rounds/day"},{"type":"rage powers","details":"intimidating glare, powerful blow +3, raging leaper +11, rolling dodge +2, unexpected strike"},{"type":"stunning fist","details":"2/day, DC 16"}],"strength":29,"dexterity":14,"constitution":18,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":11,"cmb":20,"cmd":34,"feats":[{"feat":"Dodge"},{"feat":"Improved Unarmed Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Stunning Fist"},{"feat":"Throw Anything"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":15,"special":"+4 when jumping"},{"skill":"Intimidate","value":13},{"skill":"Perception","value":15},{"skill":"Perform (act)","value":10},{"skill":"Swim","value":22}],"languages":["Common","Polyglot"],"sq":["fast movement"],"gear":"+2 heavy wooden shield, bracers of armor +3, ring of protection +1, 593 gp, potions of barkskin +2 (2)","before_combat":"Gorebeard drinks a potion of barkskin +2.","during_combat":"Gorebeard rages, then charges the closest, toughest-looking target, using Power Attack to gain a +6 bonus on damage rolls at the cost of a -3 penalty on attack rolls. He uses Stunning Fist in the first 2 rounds of combat. If he reduces a foe to fewer than 0 hit points, Gorebeard must make a DC 20 Will save to resist the compulsion to smear his beard in the victim's blood on his next turn as a move action-this provokes attacks of opportunity.","morale":"Gorebeard fights to the death.","source":"AP 59, Pathfinder RPG Advanced Player's Guide 79"},{"name":"Elder Brykolakas","cr":9,"xp":6400,"race":"brykolakas","age_category":"Adult","alignment":"CE","size":"Medium","type":"undead","sub_types":["aquatic","shapechanger"],"init":5,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+5 Dex, +6 natural","hp":123,"hd":"13d8+65","hd_value":13,"fort":10,"ref":9,"will":12,"dr":"10/silver","immunities":["undead traits"],"sr":20,"weaknesses":["water dependency"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":40}],"melee":"2 claws +16 (2d6+6/19-20 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"death throes"}],"strength":22,"dexterity":20,"intelligence":15,"wisdom":18,"charisma":19,"baseatk":9,"cmb":15,"cmd":30,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Natural Attack (claws)"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Intimidate","value":20},{"skill":"Knowledge (nature)","value":15},{"skill":"Perception","value":24},{"skill":"Stealth","value":21},{"skill":"Swim","value":27}],"languages":["Common"],"sq":["change shape (dolphin or manta ray, beast shape I)"],"special_abilities":[{"type":"Create Spawn","kind":"Su","details":"A humanoid or monstrous humanoid killed by a brykolakas rises as a lacedon in 1d4 days under the control of the brykolakas that created it."},{"type":"Death Throes","kind":"Su","details":"When reduced to 0 or fewer hit points, a brykolakas is destroyed and its body changes into a pool of deadly poison that quickly fills a 10-foot-radius spread (if underwater) or a 10-foot-diameter puddle (if on land) in 1 round. All creatures in this area are exposed to this foul venom. The poison disperses in 1 round if underwater, or 1d2 rounds if on land. Brykolakas poison: Death throes-contact; save Fort DC 20; onset 1 minute; frequency 1/round for 2 rounds; effect 1d6 Dex damage; cure 1 save. The save DC is Charisma-based."},{"type":"Disease","kind":"Su","details":"A brykolakas's claw attacks deliver a virulent disease that breaks down the victim's internal organs, resulting in internal bleeding and a gradual darkening of the skin. This supernatural disease is called brykolakas fever. The save DC is Charisma-based. Brykolakas fever: Claw-injury; save Fortitude DC 20 negates; onset 1 minute; frequency 1/day; effect 1d4 Con and 1d4 Dex damage; cure 1 save."},{"type":"Water Dependency","kind":"Ex","details":"A brykolakas can survive out of the water for 6 hours. After that, its body begins drying out, and within 1 hour, the brykolakas crumbles into dust (this doesn't activate its death throes ability) unless it can reach saltwater before the hour passes."}],"during_combat":"The brykolakases let their lacedon minions engage opponents first, using them as sacrificial troops to distract enemies and perhaps use up some resources before they step in to focus their attacks on the same foes.","morale":"A brykolakas fights until destroyed.","source":"AP 59, Tome of Horrors Complete 85"},{"name":"Alise Grogblud","cr":7,"xp":3200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":8}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex, +1 dodge","hp":71,"hd":"8d8+32","hd_value":8,"fort":4,"ref":9,"will":1,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +2"],"speed":[{"type":"land","speed":30}],"melee":"+1 scimitar +11 (1d6+4/18-20)","ranged":"mwk throwing axe +10 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+4d6"}],"strength":16,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":8,"charisma":12,"baseatk":6,"cmb":9,"cmd":23,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Martial Weapon Proficiency (scimitar)"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":12},{"skill":"Climb","value":14},{"skill":"Intimidate","value":12},{"skill":"Perception","value":10},{"skill":"Profession (sailor)","value":10},{"skill":"Stealth","value":14},{"skill":"Survival","value":7},{"skill":"Swim","value":14}],"languages":["Common"],"sq":["rogue talents (bleeding attack +4, combat trick, stand up, weapon training)","trapfinding +4"],"gear":"+2 leather armor, +1 scimitar, masterwork throwing axe, ruby worth 1,000 gp","during_combat":"Alise makes good use of Spring Attack in combat, staying on the move so she can make flanking attacks while minimizing full attacks on herself from enemies. She avoids ending her turn standing within 5 ft. of any foe.","morale":"Alise surrenders if either she's brought below 25 hit points or at least four of the other castaways are defeated. In this event, Alise throws herself upon the PCs' mercy, tearfully explaining that she feared they were assassins sent by Harrigan and begging them to rescue her and her crew from this \"cursed rock.\" If she finds out that the PCs are Harrigan's enemies, she tells them about the files her captain Scags kept on his old commander, stored in a watertight chest on the Devilish Duchess, which she knows has been claimed by the brykolakases and is in area A5. See \"Rescue and Repairs\" on page 25 for more details on how Alise can help the PCs against Harrigan.","source":"AP 59"},{"name":"Pirate Castaway","cr":4,"xp":1200,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"rogue","level":3}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 Dex, +1 dodge, +2 shield","hp":51,"hd":"2d10+3d8+23","hd_value":5,"fort":7,"ref":4,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk cutlass +9 (1d6+3/18-20)","ranged":"mwk light crossbow +6 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":16,"dexterity":13,"constitution":16,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":4,"cmb":7,"cmd":19,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (cutlass)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Appraise","value":6},{"skill":"Climb","value":11},{"skill":"Intimidate","value":7},{"skill":"Perception","value":9},{"skill":"Profession (sailor)","value":9},{"skill":"Swim","value":11}],"languages":["Common"],"sq":["rogue talents (combat trick)","trapfinding +1"],"gear":"+1 studded leather, +1 buckler, masterwork cutlass, masterwork light crossbow with 10 bolts, 60 gp","source":"AP 59"},{"name":"Captain Valerande \"barracuda\" Aiger","cr":12,"xp":19200,"race":"Half-Elf","gender":"Male","age_category":"Adult","classes":[{"class":"Inner Sea Pirate","level":8},{"class":"rogue","level":5,"archetype":"pirate"}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["elf","human"],"init":5,"senses":["low-light vision"],"ac":26,"ac_touch":17,"ac_flat_footed":20,"ac_mods":"+7 armor, +1 deflection, +5 Dex, +1 dodge, +1 natural, +1 shield","hp":76,"hd":"13d8+18","hd_value":13,"fort":5,"ref":13,"will":3,"save_mods":"+2 vs. enchantments, +1 vs. fear and mind-affecting","defensive_abilities":["evasion","uncanny dodge","unflinching*"],"speed":[{"type":"land","speed":30}],"melee":"+2 rapier +15 (1d6+4/18-20), +1 boarding axe +13 (1d6+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack +6d6 plus trip"}],"strength":14,"dexterity":20,"constitution":12,"intelligence":13,"wisdom":8,"charisma":10,"baseatk":9,"cmb":14,"cmd":28,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Improved Feint"},{"feat":"Sea Legs*"},{"feat":"Skill Focus (Bluff)"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":23},{"skill":"Appraise","value":14},{"skill":"Bluff","value":21},{"skill":"Climb","value":4},{"skill":"Intimidate","value":15},{"skill":"Perception","value":17},{"skill":"Profession (sailor)","value":15},{"skill":"Sense Motive","value":15},{"skill":"Swim","value":20}],"languages":["Common","Elven","Osiriani"],"sq":["elf blood","pirate tricks (classic duelist, deep breath, defensive climber, foot sweep, rigging monkey)","rogue talents (bleeding attack +6)","swinging reposition*"],"special_abilities":[{"type":"Pirate Tricks","kind":"Ex","details":"Barracuda gains a +1 competence bonus on attack rolls with a cutlass, rapier, or short sword. He can hold his breath for 36 rounds before risking drowning. He doesn't lose his Dex bonus to AC when climbing. If he damages a foe with sneak attack, he can try to trip that foe as an immediate action. He gains a +2 bonus on Climb checks when using ropes, and when he does so, climbs twice as quickly as normal."}],"gear":"+4 studded leather, +2 rapier, +1 boarding axe, amulet of natural armor +1, ring of protection +1","during_combat":"Barracuda uses his officers to set up flanking opportunities, barking orders to move them around the combat as needed. He uses his swinging reposition ability to try to bull rush players over the side of the ship, then moves closer to allies so he can make full attacks as soon as possible. He uses Combat Expertise if faced by particularly hard-hitting foes.","morale":"If reduced to fewer than 15 hit points, Barracuda drops his weapons and surrenders, hoping to appeal to the PCs' sense of pity at this point to claim his birthright.","source":"AP 59, Ultimate Combat 72, Pirates of the Inner Sea 24"},{"name":"Kipper","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":9}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":21,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+5 armor, +3 Dex, +1 dodge, +2 shield","hp":89,"hd":"9d8+45","hd_value":9,"fort":6,"ref":11,"will":6,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +3"],"speed":[{"type":"land","speed":30}],"melee":"mwk short sword +9 (1d6+2/19-20)","ranged":"+1 flaming composite longbow +11 (1d8+3/x3 plus 1d6 fire) or light ballista +9 (3d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+5d6"}],"strength":14,"dexterity":16,"constitution":16,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":6,"cmb":8,"cmd":22,"feats":[{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (light ballista)"},{"feat":"Iron  Will"},{"feat":"Lightning Reflexes"},{"feat":"Shield Focus"},{"feat":"Shield Proficiency"},{"feat":"Toughness"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":11},{"skill":"Climb","value":13},{"skill":"Craft (alchemy)","value":12},{"skill":"Knowledge (engineering)","value":9},{"skill":"Perception","value":13},{"skill":"Profession (sailor)","value":13},{"skill":"Stealth","value":14},{"skill":"Swim","value":13}],"languages":["Common"],"sq":["rogue talents (bleeding attack +5, combat trick, resiliency, weapon training)","trapfinding +4"],"gear":"+1 chain shirt, masterwork buckler, +1 flaming composite longbow with 20 arrows, masterwork short sword, potions of cure moderate wounds (2), potions of invisibility (2)","before_combat":"Kipper drinks a potion of invisibility as the PCs prepare to board.","during_combat":"Kipper mans a ballista, hoping to fire on a PC within 30 ft. so that he can make one of the most memorable sneak attacks of his life. He then drinks his second potion of invisibility, moves to an advantageous spot, and makes a second sneak attack against a foe with his bow. He continues to snipe with his bow until the PCs engage in melee, at which point he moves to flank, if possible, with his sword.","morale":"Kipper fights to the death.","source":"AP 59"},{"name":"Patch Patchsalt","cr":7,"xp":3200,"race":"gnome","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":5},{"class":"rogue","level":3}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["gnome"],"init":7,"senses":["low-light vision"],"ac":18,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 armor, +3 Dex, +1 dodge, +1 size","hp":82,"hd":"5d10+3d8+37","hd_value":8,"fort":8,"ref":7,"will":5,"save_mods":"+2 vs. illusions, +1 vs. fear","defensive_abilities":["bravery +1","evasion","trap sense +1"],"speed":[{"type":"land","speed":20}],"melee":"+1 Human bane short sword +12 (1d4+5/19-20)","ranged":"mwk dagger +13 (1d3+2/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"},{"type":"weapon training","details":"light blades +1"}],"strength":12,"dexterity":16,"constitution":16,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":7,"cmb":7,"cmd":21,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Toughness"},{"feat":"Weapon Focus (short sword)"},{"feat":"Weapon Specialization (short sword)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Bluff","value":11},{"skill":"Climb","value":9},{"skill":"Perception","value":11},{"skill":"Profession (sailor)","value":11},{"skill":"Stealth","value":16}],"languages":["Common","Gnome"],"sq":["armor training 1","rogue talents (combat trick)","trapfinding +1"],"gear":"+1 leather armor, +1 Human bane short sword, masterwork dagger, 554 gp","during_combat":"Patch focuses her attacks on humans, if possible, flanking where she can to maximize her damage. She prefers to fight with Riaris Krine at her side, both of them focusing their attacks on the same foe at once.","morale":"Patch fights to the death.","source":"AP 59"},{"name":"Riaris Krine","cr":7,"xp":3200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":8}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+8 armor, +2 Dex, +1 dodge","hp":80,"hd":"8d10+32","hd_value":8,"fort":8,"ref":4,"will":5,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2"],"speed":[{"type":"land","speed":15}],"melee":"+1 boarding pike +14 (1d8+8/x3) or mwk dagger +12 (1d4+4/19-20)","ranged":"mwk dagger +11 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"polearms +1"}],"strength":16,"dexterity":14,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":8,"cmb":11,"cmd":24,"feats":[{"feat":"Disruptive"},{"feat":"Dodge"},{"feat":"Greater Weapon Focus (boarding pike)"},{"feat":"Iron Will"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (boarding pike)"},{"feat":"Weapon Specialization (boarding pike)"}],"skills":[{"skill":"Climb","value":13},{"skill":"Perception","value":9},{"skill":"Profession (sailor)","value":12}],"languages":["Common"],"sq":["armor training 2"],"gear":"+2 breastplate, +1 boarding pike, masterwork daggers (5), grappling hook, rope, peg leg, potions of cure serious wounds (2)","during_combat":"Riaris uses her boarding pike's reach to attack foes being hounded by Patch Patchsalt, using Power Attack to gain a +6 bonus on damage rolls (at a cost of a -3 penalty to hit) to further her blows. She keeps an eye on spellcasters, and attempts to maximize her Disruptive feet by catching as many enemy spellcasters in her weapon's reach as possible.","morale":"Riaris fights to the death.","source":"AP 59"},{"name":"Deep Tiger Anemone","cr":13,"xp":25600,"race":"giant sea anemone","age_category":"Adult","alignment":"N","size":"Colossal","type":"vermin","sub_types":["aquatic"],"init":2,"senses":["blindsight 30 ft."],"ac":19,"ac_touch":4,"ac_flat_footed":17,"ac_mods":"+2 Dex, +15 natural, -8 size","hp":275,"hd":"19d8+190","hd_value":19,"fort":21,"ref":8,"will":6,"defensive_abilities":["amorphous"],"dr":"15/slashing","immunities":["gaze attacks","mind-affecting effects","poison","vision-based effects"],"speed":[{"type":"land","speed":10}],"melee":"tentacles +20 (8d6+21 plus grab and poison)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"fast swallow"},{"type":"poison"},{"type":"swallow whole","details":"4d6+21 bludgeoning damage, AC 17, 27 hp"},{"type":"water jet"}],"strength":38,"dexterity":14,"constitution":30,"wisdom":10,"charisma":2,"baseatk":14,"cmb":36,"cmb_special":"+40 grapple","cmd":48,"cmd_special":"can't be tripped","feats":[{"feat":"Whirlwind Attack","type":"bonus"}],"skills":[{"skill":"Stealth","value":10}],"sq":["anchored","sightless"],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Tentacle-injury; save Fort DC 29; frequency 1/ round for 6 rounds; effect 1d6 Strength drain and 1d6 Dexterity drain; cure 2 consecutive saves."},{"type":"Water Jet","kind":"Ex","details":"Once every 1d4 rounds as a swift action, a deep tiger anemone can draw large quantities of surrounding water into its body and then expel the water at high pressure. It makes a single combat maneuver check against all creatures within 30 feet-those whose CMD this roll equals or exceeds are pushed back to a maximum distance of 30 ft. from the anemone. This forced movement doesn't provoke attacks of opportunity."}],"during_combat":"The deep tiger anemone lashes out at all available targets, using its Whirlwind Attack feat to great effect. It only attempts to grab and eat one target per round.","morale":"The deep tiger anemone fights to the death, but doesn't pursue foes.","source":"AP 59, Pathfinder RPG Bestiary 3 238"},{"name":"Smuggler","cr":7,"xp":3200,"race":"human","age_category":"Adult","classes":[{"class":"rogue","level":8,"archetype":"smuggler"}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+5 armor, +4 Dex, +1 dodge","hp":63,"hd":"8d8+24","hd_value":8,"fort":5,"ref":11,"will":5,"defensive_abilities":["improved uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"+1 short sword +11 (1d6/19-20)","ranged":"mwk shortbow +11 (1d6/19-20) or light ballista +11 (3d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+4d6"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"2/day","spells":[{"spell":"disguise self"}]},{"frequency":"3/day","spells":[{"spell":"detect magic"}]}],"strength":8,"dexterity":18,"constitution":14,"intelligence":12,"wisdom":10,"charisma":14,"baseatk":6,"cmb":5,"cmd":20,"feats":[{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (light ballista)"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Bluff","value":13},{"skill":"Diplomacy","value":13},{"skill":"Disable Device","value":15},{"skill":"Disguise","value":13},{"skill":"Knowledge (engineering)","value":12},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":11},{"skill":"Sleight of Hand","value":19},{"skill":"Spellcraft","value":9},{"skill":"Stealth","value":15}],"languages":["Common","Polyglot"],"sq":["rogue talents (bleeding attack +4, finesse rogue, major magic, minor magic)","smuggler abilities (bribery, conceal item, distraction)"],"special_abilities":[{"type":"Smuggler Abilities","details":"These smugglers gain a +2 bonus on Diplomacy checks made to smuggle contraband through a checkpoint and a +4 bonus on Sleight of Hand checks. In addition, a smuggler can make a Bluff check opposed by a searcher's Perception check when a searcher looks for items the smuggler has concealed-if the smuggler makes this check, the searcher must roll a second Perception check and take the worse of the two rolls as his actual result."}],"gear":"+2 studded leather, +1 short sword, masterwork shortbow with 20 arrows, cloak of resistance +1","during_combat":"The smugglers on the roof use the ballistae against intruders-they can't target foes in area D2, though, so if the PCs move the fight down there or into the floor below, they abandon the siege engines to join the fight. Smugglers in melee combat work together to surround foes and flank, relying on their shortbows only when they can't reach a foe in melee.","morale":"The smugglers are highly trained Chelish agents- they fight to the death.","source":"AP 59, Pirates of the Inner Sea 23"},{"name":"Scrag Savage","cr":8,"xp":4800,"race":"Scrag","age_category":"Adult","classes":[{"class":"barbarian","level":3,"archetype":"sea reaver"}],"alignment":"CE","size":"Large","type":"humanoid","sub_types":["aquatic","giant"],"init":4,"senses":["darkvision 60 ft.","eyes of the storm","low-light vision","scent"],"ac":18,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+4 Dex, +7 natural, -2 rage, -1 size","hp":127,"hd":"6d8+3d12+81","hd_value":9,"hp_mods":"regeneration 5 (acid or fire, when in contact with water)","fort":17,"ref":7,"will":7,"speed":[{"type":"land","speed":25},{"type":"swim","speed":40}],"melee":"mwk handaxe +14 (1d8+9/x3), mwk handaxe +14 (1d8+9/x3), bite +10 (1d8+4) or 2 claws +15 (1d6+9), bite +15 (1d8+9)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rage","details":"15 rounds/day"},{"type":"rage powers","details":"swift foot +5 feet"},{"type":"rend","details":"2 claws, 1d6+10"}],"strength":29,"dexterity":18,"constitution":29,"intelligence":6,"wisdom":11,"charisma":4,"baseatk":7,"cmb":17,"cmd":29,"feats":[{"feat":"Double Slice"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Two-Weapon Fighting"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Climb","value":16},{"skill":"Intimidate","value":12},{"skill":"Perception","value":6},{"skill":"Profession (sailor)","value":7},{"skill":"Survival","value":6},{"skill":"Swim","value":22}],"languages":["Giant"],"sq":["amphibious","marine terror","savage sailor*"],"gear":"masterwork handaxes (2), amulet of natural armor +2","during_combat":"Even though their regeneration doesn't work out of water, the scrags are ruthless and aggressive in battle. The scrags do more damage with their axes, but if a scrag consistently misses foes, it throws the axes aside in disgust to switch to biting and clawing.","morale":"Although the scrags are charmed, this doesn't make them foolhardy. A scrag panics if brought below 25 hit points, and immediately attempts to flee the castle and into the ocean to activate its regeneration ability. If a scrag is released from a charm monster effect, it immediately realizes it's been tricked and flees into the ocean at once, abandoning its duties.","source":"AP 59, Pathfinder RPG Bestiary 268, Pathfinder RPG Ultimate Combat 29"},{"name":"Norgorber Cultist","cr":6,"xp":2400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Norgorber","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":20,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+7 armor, +1 Dex, +2 shield","hp":63,"hd":"7d8+28","hd_value":7,"fort":9,"ref":3,"will":9,"speed":[{"type":"land","speed":20}],"melee":"+1 short sword +7 (1d6+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, DC 14, 4d6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"copycat","details":"7 rounds"},{"spell":"touch of evil","details":"3 rounds"}]}],"spellsprepared_caster_level":7,"spellsprepared_concentration":11,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"confusion","type":"domain"},{"spell":"cure critical wounds"},{"spell":"poison"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"bestow curse"},{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"magic circle against good","type":"domain"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds","count":2},{"spell":"death knell"},{"spell":"invisibility","type":"domain"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"bane"},{"spell":"cure light wounds","count":2},{"spell":"disguise self D"},{"spell":"divine favor"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"stabilize"}]}],"spelldomains":"Evil, Trickery","strength":10,"dexterity":12,"constitution":14,"intelligence":8,"wisdom":18,"charisma":13,"baseatk":5,"cmb":5,"cmd":16,"feats":[{"feat":"Combat Casting"},{"feat":"Great Fortitude"},{"feat":"Selective Channeling"},{"feat":"Toughness"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Heal","value":10},{"skill":"Knowledge (arcana)","value":4},{"skill":"Knowledge (religion)","value":6},{"skill":"Profession (torturer)","value":9},{"skill":"Sense Motive","value":10}],"languages":["Common"],"gear":"+1 chainmail, +1 light wooden shield, +1 short sword, spell component pouch, silver unholy symbol of Norgorber worth 25 gp, potions of cure moderate wounds (2), potions of invisibility (2)","during_combat":"The cultists prefer playing support roles, hanging back in a battle with sanctuary or invisibility spells in effect so they can move to and fro casting healing spells on those better suited for combat. If directly confronted, they rely heavily upon their ability to channel negative energy and confusion spells.","morale":"The cultists are fanatic and fight to the death.","source":"AP 59"},{"name":"Mr. Clack","cr":12,"xp":19200,"race":"spiny eurypterid","age_category":"Adult","alignment":"N","size":"Huge","type":"vermin","sub_types":["aquatic"],"templates_applied":"advanced","init":6,"senses":["low-light vision","tremorsense 30 ft."],"ac":27,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+2 Dex, +17 natural, -2 size","hp":184,"hd":"16d8+112","hd_value":16,"fort":17,"ref":7,"will":8,"defensive_abilities":["spiny carapace"],"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":10},{"type":"swim","speed":40}],"melee":"2 claws +20 (2d6+10/19-20), sting +20 (1d6+10 plus poison)","space":"15 ft.","reach":"15 ft. (20 ft. with sting)","special_attacks":[{"type":"rend","details":"2 claws, 2d6+15"}],"strength":30,"dexterity":14,"constitution":24,"wisdom":17,"charisma":6,"baseatk":12,"cmb":24,"cmd":36,"cmd_special":"48 vs. trip","feats":[{"feat":"Improved Critical (claws)","type":"bonus"},{"feat":"Improved Initiative B"},{"feat":"Improved Natural Attack (claws) B"}],"skills":[{"skill":"Swim","value":18}],"sq":["amphibious"],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 25; frequency 1/round for 6 rounds; effect 1d4 Con and 1d2 Dex; cure 2 consecutive saves."},{"type":"Spiny Carapace","kind":"Ex","details":"Any creature that attacks Mr. Clack with a light weapon, unarmed strike, or natural attack takes 1d6 points of piercing damage from the eurypterid's spiny carapace. A creature that grapples or is grappled by Mr. Clack takes 2d6 points of piercing damage per round the grapple is maintained."}],"during_combat":"Mr. Clack attacks anyone it notices approaching its den. Note that anyone who climbs down into the sinkhole (or, for that matter, bumps the edge of the railing) is in reach of the eurypterid's sting attack. With its tremorsense, Mr. Clack can lash out through the hole at anyone in or adjacent to area D9a.","morale":"Mr. Clack is too big to pursue foes out of it den. It fights to the death.","source":"AP 59, Pathfinder #37 78"},{"name":"Luccaria","cr":11,"xp":12800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Norgorber","level":12}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":25,"ac_touch":17,"ac_flat_footed":22,"ac_mods":"+7 armor, +4 deflection, +3 Dex, +1 shield","hp":117,"hd":"12d8+60","hd_value":12,"fort":11,"ref":7,"will":12,"speed":[{"type":"land","speed":30}],"melee":"+3 grayflame short sword +14 (1d6+3/19-20), +3 short sword +14 (1d6+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"5/day, DC 18, 6d6"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charming smile","details":"12 rounds"},{"spell":"master's illusion","details":"12 rounds/day"}]},{"frequency":"7/day","spells":[{"spell":"copycat","details":"12 rounds"},{"spell":"dazing touch"}]}],"spellsprepared_caster_level":12,"spellsprepared_concentration":16,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"blade barrier"},{"spell":"heal"},{"spell":"mislead","type":"domain"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"charm monster","type":"domain"},{"spell":"flame strike"},{"spell":"quickened divine might"},{"spell":"quickened shield of faith"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"air walk"},{"spell":"greater magic weapon","count":2},{"spell":"heroism","type":"domain"},{"spell":"spell immunity"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"contagion"},{"spell":"cure serious wounds"},{"spell":"dispel magic"},{"spell":"magic vestment"},{"spell":"suggestion","type":"domain"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"cure moderate wounds","count":2},{"spell":"death knell"},{"spell":"hold person"},{"spell":"invisibility","type":"domain"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person","type":"domain"},{"spell":"cure light wounds","count":3},{"spell":"deathwatch"},{"spell":"obscuring mist"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"stabilize"}]}],"spelldomains":"Charm, Trickery","strength":10,"dexterity":16,"constitution":16,"intelligence":8,"wisdom":19,"charisma":14,"baseatk":9,"cmb":9,"cmd":26,"feats":[{"feat":"Combat Casting"},{"feat":"Quicken Spell"},{"feat":"Toughness"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Diplomacy","value":9},{"skill":"Heal","value":11},{"skill":"Intimidate","value":6},{"skill":"Knowledge (religion)","value":6},{"skill":"Profession (torturer)","value":11},{"skill":"Sense Motive","value":11}],"languages":["Common"],"gear":"+1 glamered chain shirt, +1 grayflame* short sword, masterwork short sword, headband of inspired wisdom +2, ring of mind shielding, spell component pouch, silver unholy symbol of Norgorber worth 25 gp, wand of cure serious wounds (14 charges), unholy water (2)","before_combat":"Luccaria casts greater magic weapon on her swords and magic vestment on her armor. As soon as she hears her cultists in area D9 shouting, she casts air walk, bear's endurance, and invisibility on herself. She also casts spell immunity, choosing spells she knows the PCs favor.","during_combat":"Once combat starts in area D9, and once she is invisible, Luccaria sends her two attendant cultists into area D9 as well to join the fight. She follows, casting quickened shield of faith and heroism as she enters the room. If the opportunity presents itself, she casts blade barrier to block escape routes. Once she's visible, Luccaria casts her ranged attack spells. If she's engaged in melee she casts quickened divine might before attacking, then channels negative energy as a swift action the following round to activate her grayflame short sword (which increases the weapon's enhancement bonus by +1 and deals +1d6 points of damage for 6 rounds). Luccaria casts heal on herself if she ever drops below 40 hit points.","morale":"If dropped below 15 hit points, Luccaria casts mislead and attempts to escape to Harrigan's side (in area G3) to inform him of the PCs and to aid him in combat. She doesn't abandon Harrigan as long as he lives, but if he is slain, she attempts to flee the Shackles entirely.","source":"AP 59"},{"name":"Jakaw Razorbeak","cr":10,"xp":9600,"race":"tengu","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":11}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["tengu"],"init":3,"senses":["low-light vision"],"ac":25,"ac_touch":15,"ac_flat_footed":21,"ac_mods":"+6 armor, +1 deflection, +3 Dex, +1 dodge, +3 natural, +1 shield","hp":120,"hd":"11d10+55","hd_value":11,"fort":10,"ref":10,"will":5,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":40}],"melee":"+1 scimitar +15 (1d6+5/18-20), +1 kukri +15 (1d4+5/18-20), bite +12 (1d3+4)","ranged":"mwk shortbow +15 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"aquatic humanoids +2, elves +2, humans +6"}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":8,"spellsprepared_concentration":10,"spellsprepared":[{"spell_level":3,"spell_slots":1,"spells":[{"spell":"greater magic fang"}]},{"spell_level":2,"spell_slots":2,"spells":[{"spell":"barkskin"},{"spell":"bear's endurance"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"charm animal"},{"spell":"longstrider"},{"spell":"resist energy"}]}],"strength":18,"dexterity":16,"constitution":16,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":11,"cmb":15,"cmd":30,"feats":[{"feat":"Dodge"},{"feat":"Double Slice"},{"feat":"Endurance"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Toughness"},{"feat":"Two-Weapon Defense"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (kukri)"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Bluff","value":10},{"skill":"Intimidate","value":13},{"skill":"Linguistics","value":6},{"skill":"Perception","value":16},{"skill":"Profession (sailor)","value":16},{"skill":"Stealth","value":18}],"languages":["Common","Aquan","Elven","Osiriani","Polyglot","Tengu"],"sq":["favored terrain (urban +2, water +4)","gifted linguist","hunter's bond (companions)","quarry","swift tracker","swordtrained","track +5","wild empathy +10","woodland stride"],"gear":"+2 chain shirt, +1 kukri, +1 scimitar, belt of giant strength +2, ring of protection +1, mwk shortbow, keys to areas D5 and E5, 78 gp","before_combat":"Jakaw casts barkskin, bear's endurance, greater magic fang, and longstrider if the alarm is raised.","during_combat":"Jakaw uses his hunter's bond to grant bonuses to the smugglers in the area on the first round of combat, while declaring the toughest-looking Human enemy as his quarry. If the alarm is raised, Jakaw can establish one of the PCs as his quarry early by watching them from afar if he gets the chance. Jakaw leaps into battle with a cackle once he's established quarry and granted his companions his hunter's bond, focusing his attacks on his quarry before moving on to other humans or elves if possible.","morale":"If reduced to fewer than 40 hit points, Jakaw attempts to retreat to Harrigan's side (area G3) to report his failure and then help protect his captain. He fights to the death otherwise.","source":"AP 59, Pathfinder RPG Bestiary 263"},{"name":"Gilbrok The Tongue","cr":12,"xp":19200,"race":"human","gender":"Male","age_category":"Old","classes":[{"class":"witch","level":13}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":10,"ac_touch":10,"ac_flat_footed":10,"hp":74,"hd":"13d6+26","hd_value":13,"fort":6,"ref":4,"will":12,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"mwk quarterstaff +5 (1d6-2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"agony [13 rounds], blight [130 feet], charm [2 steps, 6 rounds], evil eye [-4, 9 rounds], healing [cure moderate], misfortune [2 rounds], weather control"}],"spellsprepared_caster":"witch","spellsprepared_caster_level":13,"spellsprepared_concentration":19,"spellsprepared":[{"spell_level":7,"spell_slots":1,"spells":[{"spell":"heal"}]},{"spell_level":6,"spell_slots":3,"spells":[{"spell":"cone of cold"},{"spell":"flesh to stone"},{"spell":"mass suggestion"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"baleful polymorph"},{"spell":"dominate person"},{"spell":"geyser"},{"spell":"overland flight"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"black tentacles"},{"spell":"charm monster"},{"spell":"control water"},{"spell":"dimension door"},{"spell":"phantasmal killer"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"bestow curse"},{"spell":"dispel magic"},{"spell":"lightning bolt"},{"spell":"suggestion"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blindness/deafness"},{"spell":"detect thoughts"},{"spell":"fog cloud"},{"spell":"glitterdust"},{"spell":"hold person"},{"spell":"pox pustules"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"burning hands"},{"spell":"command"},{"spell":"cure light wounds","count":2},{"spell":"ill omen"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"message"},{"spell":"stabilize"}]}],"patron":"water","strength":7,"dexterity":10,"constitution":11,"intelligence":22,"wisdom":14,"charisma":10,"baseatk":6,"cmb":4,"cmd":16,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Casting"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Improved Great Fortitude"},{"feat":"Iron Will"},{"feat":"Skill Focus (Spellcraft)"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (alchemy)","value":22},{"skill":"Fly","value":26},{"skill":"Handle Animal","value":13},{"skill":"Knowledge (arcana)","value":22},{"skill":"Knowledge (nature)","value":22},{"skill":"Perception","value":15},{"skill":"Spellcraft","value":28},{"skill":"Survival","value":15},{"skill":"Swim","value":11}],"languages":["Common","Aklo","Aquan","Boggard","Cyclops","Osiriani","Polyglot"],"sq":["witch's familiar (monkey named Maka-ruku)"],"gear":"masterwork quarterstaff, necklace of adaptation, dust of disappearance (4 doses), potions of cure moderate wounds (3), potion of gaseous form, wand of cure moderate wounds (24 charges)","before_combat":"Gilbrok casts overland flight on himself every day.","during_combat":"Once Gilbrok finishes his weather control hex, or once he's confronted in combat, he uses a dose of dust of disappearance at once-he knows he's close to helpless in direct melee combat, and relies upon the greater invisibility afforded by the dust to survive, using flight to stay mobile and change position each round while he harries foes with his ranged attacks. Each time his dust wears out, he uses a new dose to maintain invisibility.","morale":"If reduced to fewer than 30 hit points or if his invisibility tactics aren't working (or if he runs out of dust of disappearance), Gilbrok flees to Harrigan's side in area G3 to cower behind him for protection. He won't surrender or flee at this point, but if Harrigan is slain, he immediately surrenders and begs the PCs for mercy, promising to serve them well if they spare his miserable life.","source":"AP 59, Advanced Player's Guide 65"},{"name":"Adelita Doloruso","cr":12,"xp":19200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"evoker","level":13}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":23,"ac_touch":15,"ac_flat_footed":20,"ac_mods":"+4 armor, +2 deflection, +2 Dex, +1 dodge, +4 shield","hp":126,"hd":"13d6+78","hd_value":13,"fort":12,"ref":10,"will":11,"speed":[{"type":"land","speed":30}],"melee":"wizard hook +6 (1d4)","ranged":"mwk silver dagger +9 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"intense spells","details":"+6 damage"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"elemental wall","details":"13 rounds/day"}]},{"frequency":"7/day","spells":[{"spell":"force missile","details":"1d4+6"}]}],"spellsprepared_caster":"evoker","spellsprepared_caster_level":13,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":7,"spell_slots":2,"spells":[{"spell":"prismatic spray"},{"spell":"quickened fireball"}]},{"spell_level":6,"spell_slots":3,"spells":[{"spell":"chain lightning"},{"spell":"quickened scorching ray"},{"spell":"repulsion"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"cone of cold"},{"spell":"quickened shield"},{"spell":"telekinesis"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"dimension door"},{"spell":"ice storm"},{"spell":"phantasmal killer"},{"spell":"shout"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"heroism"},{"spell":"vampiric touch","count":2}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"arcane lock"},{"spell":"flaming sphere"},{"spell":"ghoul touch"},{"spell":"gust of wind"},{"spell":"invisibility"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"burning hands"},{"spell":"mage armor"},{"spell":"magic missile","count":2},{"spell":"shocking grasp"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"light"},{"spell":"read magic"}]}],"prohibited_schools":"enchantment, transmutation","strength":8,"dexterity":14,"constitution":18,"intelligence":18,"wisdom":13,"charisma":10,"baseatk":6,"cmb":5,"cmd":20,"feats":[{"feat":"Arcane Strike"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Improved Familiar"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Intimidate","value":13},{"skill":"Knowledge (arcana)","value":20},{"skill":"Knowledge (geography)","value":13},{"skill":"Knowledge (history)","value":13},{"skill":"Knowledge (nature)","value":13},{"skill":"Perception","value":14},{"skill":"Profession (sailor)","value":17},{"skill":"Spellcraft","value":20}],"languages":["Common","Cyclops","Infernal","Osiriani","Polyglot"],"sq":["arcane bond (cacodaemon familiar)","contingency (stoneskin activates as soon as she takes any physical damage)"],"gear":"wizard hook (+1 hook hand), masterwork silver daggers (6), belt of mighty constitution +4, cloak of resistance +2, mutineer's bane earring, ring of protection +2, jewelry worth 1,200 gp, spellbook","before_combat":"Adelita casts mage armor every day.","during_combat":"Adelita hangs back at first, letting her crew move forward while she supports them with spells. She casts quickened shield on the first round, along with invisibility so she can prepare a few other spells (mirror image and heroism) before she joins in with her attack spells. She casts repulsion if too many enemies are reaching her.","morale":"Adelita fights until reduced to 40 hit points or fewer, at which point she attempts to teleport back to Harrigan's fortress to warn him of the fleet's failure. If she escapes in this manner, feel free to either have her join forces with Harrigan (if your PCs could use a bigger challenge) or join the other prisoners in the prison (area D5) after some unfortunate mutilations to her hands and tongue.","source":"AP 59"}];
